import {applyTopic,RELAYS,state,update,markPending} from './state.js';
export const topics=['smartfarm/status/online','smartfarm/device/status','smartfarm/sensor/dht11','smartfarm/emergency/status','smartfarm/config/telegram/status','smartfarm/reminder/status','smartfarm/ai/alert/status',...RELAYS.flatMap(r=>[`smartfarm/relay/${r}/status`,`smartfarm/relay/${r}/timer/status`,`smartfarm/schedule/${r}/status`])];
const headers=()=>{const token=sessionStorage.getItem('gaden-token');return token?{'x-dashboard-token':token}:{} };
export async function connect(){try{const res=await fetch('../api/mqtt/state',{headers:headers()});if(!res.ok)throw new Error('bridge unavailable');const body=await res.json();Object.entries(body.state||body).forEach(([topic,payload])=>applyTopic(topic,String(payload)));update({connected:body.connected===undefined?state.connected:body.connected,auth:body.auth||state.auth});}catch{update({connected:false})}}
export async function publish(topic,payload,relay){if(!state.connected||state.emergency?.active)throw new Error('ควบคุมไม่ได้ขณะอุปกรณ์ไม่พร้อม');if(relay&&topic.endsWith('/set')&&!topic.includes('/timer/')&&!topic.includes('/schedule/'))markPending(relay,payload);const res=await fetch('../api/mqtt/publish',{method:'POST',headers:{'content-type':'application/json',...headers()},body:JSON.stringify({topic,payload})});if(!res.ok)throw new Error((await res.json().catch(()=>({}))).error||'ส่งคำสั่งไม่สำเร็จ');return res.json()}
export function saveToken(token){sessionStorage.setItem('gaden-token',token);connect()}
